import sys

def can_form_rbs(s):
    balance = 0
    max_balance = 0
    min_balance = 0
    for c in s:
        if c == '(':
            balance += 1
        elif c == ')':
            balance -= 1
        else:
            max_balance += 1
            min_balance -= 1
        if balance + max_balance < 0:
            return False
        if balance + min_balance > 0:
            return False
    return balance == 0

def main():
    import sys
    input = sys.stdin.read().splitlines()
    t = int(input[0])
    results = []
    for i in range(1, t + 1):
        s = input[i]
        if can_form_rbs(s):
            results.append('YES')
        else:
            results.append('NO')
    print('\n'.join(results))

main()
